--
-- Table structure for table `handoveritem`
--

DROP TABLE IF EXISTS `handoveritem`;
CREATE TABLE `handoveritem` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `isGood` tinyint(1) NOT NULL,
  `handoverId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `repairNote` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `repairPhotoUrl` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `isRepaired` tinyint(1) NOT NULL DEFAULT '0',
  `adminRejectionNote` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `HandoverItem_handoverId_fkey` (`handoverId`),
  CONSTRAINT `handoveritem_handoverId_fkey` FOREIGN KEY (`handoverId`) REFERENCES `handover` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

