DROP TABLE IF EXISTS `password_reset_request`;
CREATE TABLE `password_reset_request` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `userId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `reason` text COLLATE utf8mb4_unicode_ci,
  `status` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `adminNotes` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `resetByAdminId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `newPasswordHash` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `resetAt` datetime(3) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `password_reset_request_status_idx` (`status`),
  KEY `password_reset_request_userId_idx` (`userId`),
  KEY `password_reset_request_resetByAdminId_fkey` (`resetByAdminId`),
  CONSTRAINT `password_reset_request_resetByAdminId_fkey` FOREIGN KEY (`resetByAdminId`) REFERENCES `user` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `password_reset_request_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

